const texts = ["42", "3.75", "12px", ""];
const values = [5, 5.5, 1 / 0];

for (const text of texts) {
  console.log(`"${text}": Number ${Number(text)}, parseInt ${parseInt(text, 10)}, parseFloat ${parseFloat(text)}`);
}

for (const value of values) {
  console.log(`${value}: integer ${Number.isInteger(value)}, finite ${Number.isFinite(value)}`);
}

