const sizes = ["16px", "2.5em", "100%"];
const values = [10 / 2, 10 / 4, 1 / 0];

// TODO: print each size with its parseInt and parseFloat values, and add the parseFloat value to a total
// TODO: print the total
// TODO: print integer and finite checks for each value

practice.solution:
const sizes = ["16px", "2.5em", "100%"];
const values = [10 / 2, 10 / 4, 1 / 0];

let total = 0;
for (const size of sizes) {
  const amount = parseFloat(size);
  console.log(`${size}: parseInt ${parseInt(size, 10)}, parseFloat ${amount}`);
  total += amount;
}
console.log(`Total: ${total}`);

for (const value of values) {
  console.log(`${value}: integer ${Number.isInteger(value)}, finite ${Number.isFinite(value)}`);
}
